"""Find a Native yield-sign actor whose trigger contains the approach point.

This tests physical sign governance. Official status and properly erected face
still need Native map and original-camera review.
"""


def find_governing_yield_sign(world, approach_waypoint):
    point = approach_waypoint.transform.location
    matches = []
    for sign in world.get_actors().filter("traffic.yield*"):
        if sign.trigger_volume.contains(point, sign.get_transform()):
            matches.append(sign)
    if len(matches) != 1:
        raise ValueError(f"Expected one governing yield sign, found {len(matches)}")
    return matches[0]

"""Lossless original BGRA source-camera writer; caller joins Native frame IDs."""
import subprocess
from pathlib import Path


class FFV1Writer:
    def __init__(self, path, width, height, fps=20):
        path = Path(path)
        if path.exists() or width <= 0 or height <= 0 or fps <= 0:
            raise ValueError('Fresh path and positive source dimensions/rate required')
        self.path, self.width, self.height, self.fps = path, width, height, fps
        self.frames = 0
        self.exit_code = None
        self.process = subprocess.Popen([
            'ffmpeg', '-hide_banner', '-loglevel', 'error', '-n',
            '-f', 'rawvideo', '-pixel_format', 'bgra',
            '-video_size', f'{width}x{height}', '-framerate', str(fps),
            '-i', 'pipe:0', '-an', '-c:v', 'ffv1', '-level', '3',
            '-pix_fmt', 'bgr0', str(path)],
            stdin=subprocess.PIPE, stderr=subprocess.PIPE)

    def write(self, bgra):
        if not isinstance(bgra, bytes) or len(bgra) != self.width * self.height * 4:
            raise ValueError('Native BGRA source frame size mismatch')
        if self.process.poll() is not None:
            raise ValueError('Source encoder exited before frame closure')
        self.process.stdin.write(bgra)
        self.frames += 1

    def close(self):
        if self.process.stdin and not self.process.stdin.closed:
            self.process.stdin.close()
        code = self.process.wait(timeout=60)
        self.exit_code = code
        error = self.process.stderr.read().decode(errors='replace')
        self.process.stderr.close()
        if code != 0 or self.frames == 0 or not self.path.is_file():
            raise ValueError('FFV1 source encoder failed: ' + error[-1000:])
        return {'path': str(self.path), 'frames': self.frames,
                'width': self.width, 'height': self.height, 'fps': self.fps,
                'encoding': 'ffv1-lossless'}

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

"""Native yield-sign crossing sources with four original camera frame identities."""
from contextlib import contextmanager
import json
import math

CAMERAS = {'overview': (1920,1080), 'approach': (1280,720),
           'reference_corner': (1280,720), 'driver_reference': (1280,720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(CAMERAS):
        raise ValueError('All four named source-camera transforms required')
    sensors=[]
    try:
        for name,(width,height) in CAMERAS.items():
            blueprint=world.get_blueprint_library().find('sensor.camera.rgb')
            if blueprint is None:
                raise ValueError('Native RGB camera blueprint missing')
            for key,value in (('image_size_x',width),('image_size_y',height),
                              ('fov',90),('sensor_tick',.05)):
                blueprint.set_attribute(key,str(value))
            kwargs={'attach_to':ego} if name=='driver_reference' else {}
            sensor=world.spawn_actor(blueprint,transforms[name],**kwargs)
            if sensor is None:
                raise ValueError('Native source-camera spawn failed: '+name)
            sensors.append((name,sensor))
        yield dict(sensors)
    finally:
        for _,sensor in reversed(sensors):
            sensor.stop();sensor.destroy()


def _finite(value,label):
    if type(value) not in (int,float) or not math.isfinite(value):
        raise ValueError('Finite Native '+label+' required')
    return float(value)


def _body(actor,world_map,scene,role):
    pose=actor.get_transform()
    vertices=actor.bounding_box.get_world_vertices(pose)
    if len(vertices)<4:
        raise ValueError('Complete original Native body required')
    waypoint=world_map.get_waypoint(actor.get_location(),project_to_road=False)
    if waypoint is None:
        raise ValueError('Original Native waypoint missing')
    expected=scene['approaches'][role]
    if waypoint.road_id!=expected['road_id'] and not waypoint.is_junction:
        raise ValueError('Native approach road differs from scene')
    return {'actor_id':actor.id,'intersection_id':scene['intersection_id'],
            'road_id':expected['road_id'],
            'native_road_id':waypoint.road_id,'native_lane_id':waypoint.lane_id,
            'body_vertices_xy_m':[[_finite(v.x,'body x'),_finite(v.y,'body y')]
                                   for v in vertices],
            'position_xy_m':[_finite(pose.location.x,'x'),_finite(pose.location.y,'y')]}


def record_sample(frame_map,stream,snapshot,world_map,ego,other,sign,
                  camera_frames,scene,other_left_turn_intended=None):
    if set(camera_frames)!=set(CAMERAS) or any(
        camera_frames[name]!=snapshot.frame for name in CAMERAS):
        raise ValueError('All four camera frames must join the Native tick')
    if sign.id!=scene['yield_sign']['native_id']:
        raise ValueError('Governing Native yield sign changed')
    if scene['approach_relation']=='opposite_directions' and other_left_turn_intended is not True:
        raise ValueError('Original left-turn intention required')
    time_s=_finite(snapshot.timestamp.elapsed_seconds,'time')
    ego_row=_body(ego,world_map,scene,'ego')
    other_row=_body(other,world_map,scene,'other')
    if ego_row['actor_id']==other_row['actor_id']:
        raise ValueError('Distinct Native vehicle IDs required')
    mapped=frame_map.append(snapshot.frame,time_s)
    row={'frame':snapshot.frame,'time_s':time_s,
         'governing_yield_sign_id':sign.id,
         'other_left_turn_intended':other_left_turn_intended,
         'ego':ego_row,'other':other_row}
    stream.write(json.dumps(row,allow_nan=False)+'\n')
    return mapped,row

"""Source-bound entry-time and right-side geometry at one median crossing.

The elapsed time is reported without inventing a legal 'approximately' cutoff.
The official yield-sign exclusion remains a separate review question.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


REQUIRED=("crossing_history.jsonl","video_frames.jsonl","junction_context.json")


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _body(actor):
    values=actor.get("body_vertices_xy_m")
    if not isinstance(values,list) or len(values)<4:
        raise ValueError("Missing complete body")
    points=[]
    for point in values:
        if not isinstance(point,list) or len(point)!=2:raise ValueError("Invalid body vertex")
        points.append((_number(point[0],"body x"),_number(point[1],"body y")))
    body=MultiPoint(points).convex_hull
    if body.area<=0:raise ValueError("Degenerate body")
    return body


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"junction_context.json").read_text())
    for key in ("native_map_id","intersection_id","ego_highway_id","other_highway_id",
                "ego_road_id","other_road_id","crossing_geometry_source",
                "all_entrances_source","sign_governance_source","sign_face_video_source","native_yield_sign_id",
                "median_spacing_source"):
        if ctx.get(key) is None:raise ValueError("Missing sourced crossing context: "+key)
    relation=ctx.get("approach_relation","different_highways")
    if relation=="different_highways":
        if ctx["ego_highway_id"]==ctx["other_highway_id"]:
            raise ValueError("Approaches are not from different highways")
    elif relation=="opposite_directions":
        if ctx["ego_highway_id"]!=ctx["other_highway_id"]:
            raise ValueError("Opposite approaches must share a highway")
        if ctx.get("turn_intent_source")!="controller_history.jsonl":
            raise ValueError("Opposite left-turn intention needs original controller source")
        other_forward=ctx.get("other_approach_forward_xy")
        ego_forward=ctx.get("ego_approach_forward_xy")
        if (not isinstance(other_forward,list) or not isinstance(ego_forward,list) or
                len(other_forward)!=2 or len(ego_forward)!=2):
            raise ValueError("Opposite approach headings required")
        ox,oy=(_number(v,"other approach direction") for v in other_forward)
        ex,ey=(_number(v,"ego approach direction") for v in ego_forward)
        norm=math.hypot(ox,oy)*math.hypot(ex,ey)
        if norm==0 or (ox*ex+oy*ey)/norm>-.8:
            raise ValueError("Approaches are not opposite")
    else:
        raise ValueError("Unknown approach relation")
    if ctx.get("same_statutory_crossing") is not True:
        raise ValueError("One median-opening roadway crossing not sourced")
    polygon=Polygon(ctx.get("intersection_polygon_xy_m",[]))
    if not polygon.is_valid or polygon.area<=0:raise ValueError("Invalid crossing polygon")
    rows,frames=_rows(root/"crossing_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<3 or len(rows)!=len(frames):raise ValueError("Incomplete entry history")
    first={"ego":None,"other":None};start={};samples=[];previous=(-1,-math.inf)
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original video frame join failed")
        if row.get("governing_yield_sign_id")!=ctx["native_yield_sign_id"]:
            raise ValueError("Governing Native yield sign identity mismatch")
        if relation=="opposite_directions" and row.get("other_left_turn_intended") is not True:
            raise ValueError("Original left-turn intention missing")
        sample={"frame":fid,"time_s":time}
        for role in ("ego","other"):
            actor=row.get(role)
            if not isinstance(actor,dict) or actor.get("intersection_id")!=ctx["intersection_id"] or actor.get("road_id")!=ctx[role+"_road_id"]:
                raise ValueError("Participant crossing identity mismatch")
            body=_body(actor);inside=body.intersects(polygon)
            if i==0:
                if inside:raise ValueError("Missing pre-entry history")
                start[role]=(body.centroid.x,body.centroid.y)
            if inside and first[role] is None:first[role]={"frame":fid,"time_s":time}
            sample[role]={"body_in_crossing":inside}
        samples.append(sample)
    if not all(first.values()):raise ValueError("Both original body entries required")
    if relation=="opposite_directions":
        center=polygon.centroid
        for role in ("ego","other"):
            hx,hy=(_number(v,role+" approach direction") for v in ctx[role+"_approach_forward_xy"])
            toward=(center.x-start[role][0],center.y-start[role][1])
            length=math.hypot(hx,hy)*math.hypot(*toward)
            if length==0 or (hx*toward[0]+hy*toward[1])/length<.7:
                raise ValueError("Original "+role+" approach does not match heading")
    forward=ctx.get("ego_approach_forward_xy")
    if not isinstance(forward,list) or len(forward)!=2:raise ValueError("Ego approach bearing missing")
    fx,fy=(_number(v,"approach direction") for v in forward)
    norm=math.hypot(fx,fy)
    if norm==0:raise ValueError("Zero approach direction")
    dx=start["other"][0]-start["ego"][0]
    dy=start["other"][1]-start["ego"][1]
    right_cross=(fx*dy-fy*dx)/norm
    return {"format":"worker-median-crossing-entry-timing","sources":hashes,
            "approach_relation":relation,
            "first_body_entry":first,"absolute_entry_time_difference_s":abs(first["ego"]["time_s"]-first["other"]["time_s"]),
            "other_spatially_right_of_ego_approach":right_cross<0 if relation=="different_highways" else None,
            "other_right_signed_cross_m":right_cross,"samples":samples,
            "approximately_same_time_judgment":"unresolved; no legal numeric window",
            "opposite_direction_left_turn_exception_judgment":"unresolved",
            "official_yield_sign_exclusion_judgment":"unresolved",
            "yield_judgment":"unresolved","legal_conclusion":"unresolved"}
